CREATE FUNCTION firstten_policy_test.gl_session(label text)RETURNS text LANGUAGE sql STABLE AS $$SELECT result->>'sessionToken'FROM firstten_policy_test.gl_results WHERE gl_results.label=$1$$;
CREATE FUNCTION firstten_policy_test.gl_doc(label text)RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT document FROM firstten_policy_test.gl_documents WHERE gl_documents.label=$1$$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.gl_session(text),firstten_policy_test.gl_doc(text)TO authenticated,service_role;
