-- Bounded rate and intent capacity do not prevent irreversible privacy restrictions.
INSERT INTO firstten_private.guest_learning_buckets(principal_id,window_start,attempts)VALUES((SELECT(result#>>'{data,principalId}')::uuid FROM firstten_policy_test.gl_results WHERE label='a'),date_trunc('minute',clock_timestamp()),120)ON CONFLICT(principal_id)DO UPDATE SET window_start=excluded.window_start,attempts=120;
